/**
 * Entrada temporaria de navegador, usada apenas para gerar o bundle da landing
 * page enquanto `src/index.ts` ainda importa modulos que outras equipes estao
 * terminando: `ui/dialog`, `ui/components`, `charts`, `forms/validate`,
 * `forms/mask`, `directives/ui`, `directives/forms` e `devtools/xray`.
 *
 * Repete o comportamento de `src/browser.ts`, porem montando o objeto `V`
 * somente com os modulos que ja existem no repositorio. Este arquivo deve ser
 * apagado assim que `npm run build` voltar a funcionar na raiz.
 */

import { core } from './core';
import { query, ready, VoodooCollection, fromHtml } from './dom/query';
import { router, route, navigate, resolve as resolveRoute } from './router';
import { i18n, t, setLocale, getLocale } from './i18n';
import { devtoolsBus } from './devtools/bus';
import { magic } from './runtime/scope';
import { config } from './runtime/registry';
import { theme } from './storage';
import { palette, initPalette } from './ui/palette';
import {
  animate,
  spring,
  stagger,
  inView,
  scrollProgress,
  motionPresets,
  easings,
} from './motion';

// Efeitos colaterais: registram as directives de movimento.
import './motion';

const V = ((input?: unknown, context?: unknown) =>
  query(input as never, context as never)) as unknown as Record<string, unknown>;

Object.assign(V, core, {
  query,
  ready,
  fromHtml,
  Collection: VoodooCollection,

  router,
  route,
  navigate,
  resolveRoute,

  i18n,
  t,
  setLocale,
  getLocale,

  animate,
  spring,
  stagger,
  inView,
  scrollProgress,
  motion: motionPresets,
  motionPresets,
  easings,

  palette,

  devtools: devtoolsBus,
  magic,
});

/** Le a configuracao declarada na propria tag `<script>`. */
function readScriptOptions(): { manual: boolean } {
  if (typeof document === 'undefined') return { manual: false };

  const script =
    (document.currentScript as HTMLScriptElement | null) ??
    document.querySelector<HTMLScriptElement>('script[src*="voodoo"]');

  if (!script) return { manual: false };

  const manual = script.hasAttribute('data-manual') || script.hasAttribute('data-defer-init');

  const prefix = script.getAttribute('data-prefix');
  if (prefix) config.prefix = prefix;

  const baseURL = script.getAttribute('data-base-url');
  if (baseURL) {
    config.baseURL = baseURL;
    core.http.setBaseURL(baseURL);
  }

  const locale = script.getAttribute('data-locale');
  if (locale) config.locale = locale;

  if (script.hasAttribute('data-devtools')) config.devtools = true;
  if (script.hasAttribute('data-no-styles')) config.injectStyles = false;
  if (script.hasAttribute('data-no-observer')) config.autoDiscover = false;

  return { manual };
}

const options = readScriptOptions();

if (typeof window !== 'undefined') {
  const globalScope = window as unknown as Record<string, unknown>;
  globalScope.V = V;
  globalScope.Voodoo = V;

  if (!options.manual && config.autoStart) {
    const boot = (): void => {
      theme.init();
      initPalette();
      core.start();
    };

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', boot, { once: true });
    } else {
      boot();
    }
  }
}

export default V;
